package dev.playermanager.bridge.bukkit;

import dev.playermanager.bridge.assets.PackScanner;
import dev.playermanager.bridge.assets.PackSource;
import dev.playermanager.bridge.spi.PackSourceProvider;
import java.io.File;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;

/**
 * Resource packs that already exist on this server, as a pack stack (see {@link PackScanner} for the order): packs generated by
 * Nexo / Oraxen / ItemsAdder / CraftEngine / ModelEngine / BetterModel / MythicCrucible / Nova / HMCCosmetics, a bounded generic scan
 * of {@code plugins/*&#47;}, a local {@code resource-pack} from {@code server.properties}, extra paths from
 * {@code config.json platform.asset_paths}, and on top the local zip whose SHA-1 equals the pack the server really sends.
 * A remote pack URL is never downloaded.
 */
final class PackLocator implements PackSourceProvider {
    private final Ctx ctx;
    private final PackScanner scanner;
    final SentPacks sent;

    PackLocator(Ctx ctx) {
        this.ctx = ctx;
        this.scanner = new PackScanner(ctx.root, ctx.log);
        this.sent = new SentPacks(ctx);
    }

    public List<PackSource> packs() {
        Path root = ctx.root;
        List<Path> server = new ArrayList<Path>();
        Properties pr = SentPacks.serverProperties(root);
        String rp = pr == null ? null : pr.getProperty("resource-pack");
        if (rp != null && !rp.trim().isEmpty() && !rp.trim().matches("(?i)^[a-z][a-z0-9+.-]*://.*")) server.add(resolve(root, rp.trim()));
        server.addAll(sent.files());
        List<Path> operator = new ArrayList<Path>();
        for (String p : ctx.config.platformStrings("asset_paths", new ArrayList<String>())) operator.add(resolve(root, p));
        return scanner.stack(server, operator, sent.hashes(root));
    }

    private static Path resolve(Path root, String p) {
        if (p.contains("..")) return root.resolve("__invalid__");
        Path x = new File(p).isAbsolute() ? new File(p).toPath() : root.resolve(p);
        return x.normalize();
    }
}
